return $input.all().map((item, index) => {
  const mail = item.json;
  const string = (value) => typeof value === 'string' ? value : '';
  const remitentes = (Array.isArray(mail.from?.value) ? mail.from.value : [])
    .map((entry) => ({ nombre: string(entry?.name), correo: string(entry?.address).trim().toLowerCase() }))
    .filter((entry) => entry.correo);
  const texto = string(mail.text);
  const html = string(mail.html);
  const adjuntos = Object.entries(item.binary ?? {}).map(([propiedad, archivo]) => ({
    propiedad_binaria: propiedad,
    nombre: archivo.fileName ?? null,
    mime_type: archivo.mimeType ?? null,
    tamano: archivo.fileSize ?? null
  }));
  const resultado = {
    json: {
      origen: 'correo',
      message_id: string(mail.messageId).trim() || null,
      imap_uid: mail.attributes?.uid ?? null,
      remitente: remitentes.length === 1 ? remitentes[0] : null,
      remitentes,
      remitente_original: string(mail.from?.text),
      asunto: string(mail.subject),
      cuerpo: { texto, html },
      fecha_correo: mail.date ?? null,
      tiene_adjuntos: adjuntos.length > 0,
      cantidad_adjuntos: adjuntos.length,
      adjuntos
    },
    pairedItem: { item: index }
  };
  if (item.binary) resultado.binary = item.binary;
  return resultado;
});

// Decide qué hacer con cada correo: crear la solicitud (remitente con cuenta de estudiante) o
// responderle cómo registrarse. La automatización no decide el trámite: si el tipo no es claro, la
// solicitud queda por revisar con el motivo y una persona lo confirma (#28).
const correos = $('Extraer datos del correo').all();
const perfiles = $('Buscar perfiles').all().map((item) => item.json).filter((perfil) => perfil.correo);
const porCorreo = new Map(perfiles.map((perfil) => [perfil.correo.toLowerCase(), perfil]));
const app = $env.APP_URL.replace(/\/$/, '');
// CORREO_REMITENTE es "Nombre <correo>" o solo el correo: es el buzón del proyecto.
const remitenteProyecto = $env.CORREO_REMITENTE ?? '';
const buzon = (remitenteProyecto.match(/<([^>]+)>/)?.[1] ?? remitenteProyecto).trim().toLowerCase();

// Palabras clave sobre el texto sin tildes. Espejo de ETIQUETA_TIPO (web/src/lib/dominio.ts).
const REGLAS = [
  ['homologacion', /homolog/],
  ['cancelacion_extemporanea', /cancel/],
  ['supletorio', /supletori/],
  ['reingreso', /reingres|reintegr/],
  ['comite_curricular', /comite|prerrequisit|practica empresarial|enfasis/],
];
const TIPOS = {
  homologacion: 'Homologación',
  cancelacion_extemporanea: 'Cancelación extemporánea',
  supletorio: 'Supletorio',
  reingreso: 'Reingreso',
  comite_curricular: 'Solicitud al comité curricular',
};

// Mismas reglas que el bucket `adjuntos` y que nombreArchivoSeguro() de la web.
const PERMITIDOS = ['application/pdf', 'image/jpeg', 'image/png'];
const TAMANO_MAXIMO = 10 * 1024 * 1024;

const sinTildes = (texto) => texto.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const tiposEn = (texto) => REGLAS.filter(([, regla]) => regla.test(sinTildes(texto))).map(([tipo]) => tipo);
const esc = (texto) => String(texto ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const nombreSeguro = (nombre) =>
  nombre.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9._-]+/g, '-')
    .replace(/-+/g, '-').replace(/^[-.]+/, '').slice(-100) || 'adjunto';
// n8n describe el tamaño como texto ("1.2 MB"); si no se entiende, el bucket tiene la última palabra.
const bytes = (tamano) => {
  const partes = String(tamano ?? '').match(/^([\d.]+)\s*(B|kB|KB|MB|GB)$/);
  if (!partes) return 0;
  return Number(partes[1]) * { B: 1, kB: 1e3, KB: 1e3, MB: 1e6, GB: 1e9 }[partes[2]];
};
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.floor(Math.random() * 16);
  return (c === 'x' ? r : (r % 4) + 8).toString(16);
});
const textoPlano = (html) => html.replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ').replace(/<br\s*\/?>|<\/p>/gi, '\n')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/[ \t]+/g, ' ');

const salida = [];

for (const item of correos) {
  const correo = item.json;
  const remitente = correo.remitente?.correo ?? '';
  // Sin un remitente único, del propio buzón o automático (rebotes, "no responder"): se ignora, para
  // no contestarle a una máquina en un ciclo.
  if (!remitente || remitente === buzon || /^(mailer-daemon|postmaster|no-?reply)@/.test(remitente)) continue;

  const perfil = porCorreo.get(remitente);
  const asuntoOriginal = correo.asunto.trim();

  if (perfil?.rol !== 'estudiante') {
    const explicacion = perfil
      ? 'pertenece al personal de la coordinación. Las solicitudes por correo solo se reciben de cuentas de estudiante.'
      : `no corresponde a ninguna cuenta de estudiante. Crea tu cuenta con este mismo correo en <a href="${app}/registro">${app}/registro</a> y vuelve a enviarla, o regístrala directamente en la web.`;
    salida.push({
      json: {
        accion: 'responder',
        solicitud_id: null,
        tipo_aviso: 'remitente_desconocido',
        destinatario: remitente,
        asunto: 'No pudimos registrar tu solicitud - Gestión de Solicitudes',
        cuerpo: `<h2>No pudimos registrar tu solicitud</h2>
<p>Recibimos tu correo${asuntoOriginal ? ` «${esc(asuntoOriginal)}»` : ''}, pero no creamos ninguna solicitud: la dirección ${esc(remitente)} ${explicacion}</p>`,
      },
      pairedItem: { item: 0 },
    });
    continue;
  }

  const motivos = [];
  const texto = (correo.cuerpo.texto || textoPlano(correo.cuerpo.html))
    .replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (!texto) motivos.push('El correo llegó sin texto.');

  // Un solo trámite en todo el correo: ese. Varios: el del asunto si es uno, por revisar igual.
  const enAsunto = tiposEn(asuntoOriginal);
  const enTodo = tiposEn(`${asuntoOriginal}\n${texto}`);
  let tipo = 'otro';
  if (enTodo.length === 1) {
    tipo = enTodo[0];
  } else if (enTodo.length === 0) {
    motivos.push('No se pudo identificar el tipo de trámite en el correo.');
  } else {
    if (enAsunto.length === 1) tipo = enAsunto[0];
    motivos.push(`El correo menciona varios trámites (${enTodo.map((t) => TIPOS[t]).join(', ')}): confirma el tipo.`);
  }

  // Un adjunto por solicitud, como en la web. Se prefiere un PDF; las imágenes que sobran suelen ser
  // firmas o logos incrustados y no se mencionan. Lo demás que no se guarda queda en el motivo.
  const adjuntos = correo.adjuntos ?? [];
  const validos = adjuntos.filter((a) => PERMITIDOS.includes(a.mime_type) && bytes(a.tamano) <= TAMANO_MAXIMO);
  const elegido = validos.find((a) => a.mime_type === 'application/pdf') ?? validos[0] ?? null;
  const descartados = adjuntos.filter((a) => a !== elegido && !(validos.includes(a) && a.mime_type.startsWith('image/')));
  if (descartados.length) {
    motivos.push(`No se guardó: ${descartados.map((a) => a.nombre ?? 'adjunto sin nombre').join(', ')} (solo un PDF, JPG o PNG de hasta 10 MB).`);
  }

  const id = uuid();
  const ruta = elegido ? `${perfil.id}/${id}/${nombreSeguro(elegido.nombre ?? 'adjunto')}` : null;
  salida.push({
    json: {
      accion: 'crear',
      // Fila de `solicitudes`. El id va desde aquí porque la ruta del adjunto lo incluye
      // (restricción adjunto_en_carpeta_propia) y el archivo se sube antes del INSERT, que dispara F1.
      fila: {
        id,
        estudiante_id: perfil.id,
        tipo,
        asunto: (asuntoOriginal || texto.split('\n')[0] || 'Solicitud recibida por correo').slice(0, 200),
        descripcion: (texto || '(El correo llegó sin texto.)').slice(0, 20000),
        adjunto_path: ruta,
        origen: 'correo',
        revision: motivos.length ? 'por_revisar' : 'ok',
        motivo_revision: motivos.length ? motivos.join(' ').slice(0, 500) : null,
      },
      adjunto: elegido ? { ruta, mime_type: elegido.mime_type } : null,
    },
    ...(elegido ? { binary: { adjunto: item.binary[elegido.propiedad_binaria] } } : {}),
    pairedItem: { item: 0 },
  });
}

return salida;
